cat >> test/app.test.ts <<'EOF'

const refundCalls = async (paymentId: string) =>
  (await pool.query("select count(*)::int as n from payment_calls where kind = 'refund' and payment_id = $1", [paymentId])).rows[0].n;

test("refund: someone else's order and unknown ids are 404", async () => {
  const other = await fetch(`${base}/orders/3/refund`, { method: "POST", headers: as("alice-token") });
  assert.equal(other.status, 404);
  const bad = await fetch(`${base}/orders/abc/refund`, { method: "POST", headers: as("alice-token") });
  assert.equal(bad.status, 404);
  const missing = await fetch(`${base}/orders/9999/refund`, { method: "POST", headers: as("alice-token") });
  assert.equal(missing.status, 404);
  assert.equal((await pool.query("select status from orders where id = 3")).rows[0].status, "paid");
});

test("refund: parallel requests refund a paid order once", async () => {
  const results = await Promise.all(
    Array.from({ length: 10 }, () => fetch(`${base}/orders/1/refund`, { method: "POST", headers: as("alice-token") })),
  );
  const statuses = results.map((r) => r.status).sort();
  assert.equal(statuses.filter((s) => s === 200).length, 1);
  assert.ok(statuses.every((s) => s === 200 || s === 409));
  assert.equal((await pool.query("select status from orders where id = 1")).rows[0].status, "refunded");
  assert.equal(await refundCalls("pay_seed_1"), 1);
  const again = await fetch(`${base}/orders/1/refund`, { method: "POST", headers: as("alice-token") });
  assert.equal(again.status, 409);
});

test("refund: pending orders are rejected, admin can refund any paid order", async () => {
  await pool.query("update orders set status = 'pending' where id = 2");
  const pending = await fetch(`${base}/orders/2/refund`, { method: "POST", headers: as("alice-token") });
  assert.equal(pending.status, 409);
  assert.equal(await refundCalls("pay_seed_2"), 0);
  const admin = await fetch(`${base}/orders/3/refund`, { method: "POST", headers: as("admin-token") });
  assert.equal(admin.status, 200);
  assert.equal(await refundCalls("pay_seed_3"), 1);
});
EOF
